import {readFileSync} from 'node:fs';
// Read-only parent comparison: keep the actual module URLs/import resolution
// and all other current files, replacing only these two owned source texts.
const sources=new Map([
 [new URL('../src/simulation/game.js',import.meta.url).href,new URL('./harvest-consequence-base-game.js',import.meta.url)],
 [new URL('../src/microevents/economy.js',import.meta.url).href,new URL('./harvest-consequence-base-economy.js',import.meta.url)]
]);
export async function load(url,context,nextLoad){
 const source=sources.get(url);
 if(source)return {format:'module',source:readFileSync(source,'utf8'),shortCircuit:true};
 return nextLoad(url,context);
}
